(() => { window.GravewrightSDK.register({id:"scene-navigation-e2e",async ready(sdk){
  sdk.ui.slots.register("dock.actions",host=>{const root=document.createElement("section");root.dataset.testid="scene-navigation-controls";root.innerHTML='<input data-testid="scene-navigation-recipients" aria-label="Recipient ids"><input data-testid="scene-navigation-scene" aria-label="Destination scene"><button type="button" data-testid="scene-navigation-run">Run transition</button><output data-testid="scene-navigation-state">idle</output>';const state=root.querySelector("output");const report=value=>{state.textContent=value;document.body.dataset.sceneNavigationState=value;document.body.dataset.sceneNavigationHistory=`${document.body.dataset.sceneNavigationHistory||""},${value}`;};root.querySelector("button").onclick=async()=>{const ids=root.querySelector('[data-testid="scene-navigation-recipients"]').value.split(",").filter(Boolean);const sceneId=root.querySelector('[data-testid="scene-navigation-scene"]').value;try{report("fade-out");const out=await sdk.ui.presentations.show({mode:"fade",content:{value:1},audience:{kind:"users",ids},duration:1,completion:{policy:"all-connected-recipients",timeoutMs:2000}});await sdk.ui.presentations.wait(out.id,{timeoutMs:5000});report("navigation");await sdk.navigation.scene.go({sceneId,recipients:{kind:"users",ids},reason:"scene-navigation"});report("title");const title=await sdk.ui.presentations.show({mode:"title-card",sceneId,content:{title:"Scene B"},audience:{kind:"users",ids},duration:1,completion:{policy:"all-connected-recipients",timeoutMs:2000}});await sdk.ui.presentations.wait(title.id,{timeoutMs:5000});report("fade-in");const enter=await sdk.ui.presentations.show({mode:"fade",sceneId,content:{value:0},audience:{kind:"users",ids},duration:1,completion:{policy:"all-connected-recipients",timeoutMs:2000}});await sdk.ui.presentations.wait(enter.id,{timeoutMs:5000});report("done");}catch(error){report(`error:${error.message}`);}};host.append(root);});
}}); })();
